------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})
local tv     = "desc:Samsung Electric Company SAMSUNG 0x01000E00"
local lenovo = "desc:Lenovo Group Limited R45w-30 UPP040ZY"

-- Desk: Samsung 4K TV on the left (scale 2 = 1920x1080 logical), Lenovo 32:9 ultrawide
-- at 165Hz to its right. The TV's 4K@60 sits at the HDMI 2.0 limit, so its link drops now and then.
hl.monitor({
    output   = tv,
    mode     = "3840x2160@60",
    position = "0x0",
    scale    = 2,
})
hl.monitor({
    output   = lenovo,
    mode     = "5120x1440@165",
    position = "1920x0",
    scale    = 1,
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
-- Apps go through uwsm-app so each gets its own systemd scope: an OOM kill then takes one app,
-- not the compositor's cgroup (and with it the session).
local terminal    = "uwsm-app -- kitty"
local fileManager = "uwsm-app -- nautilus"
local menu        = "pkill -x wofi || uwsm-app -- wofi"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

-- waybar, hyprpaper and hypridle run as systemd user services (local-setup.sh enables them).
-- The polkit agent shows the password prompt when an app asks for admin rights.
hl.on("hyprland.start", function ()
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    -- Fullscreen XWayland games go to the TV at 4K, not the ultrawide XWayland picked as primary
    hl.exec_cmd(os.getenv("HOME") .. "/.local/bin/jmpd-xwayland-primary '" .. tv:sub(6) .. "'")
end)


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- NVIDIA as the only GPU (the RTX 3090 desktop): it drives the screens, so VA-API and GLX use its
-- driver too. Not on the laptop, where the panel is on the AMD iGPU and forcing these gives
-- Chromium (Brave) black video. Same test as nvidia_only in local-setup.sh.
local gpus = io.popen([[for d in /sys/bus/pci/devices/*; do
    case "$(cat "$d/class")" in 0x03*) cat "$d/vendor" ;; esac
done | sort -u]])
if gpus and gpus:read("a") == "0x10de\n" then
    hl.env("NVD_BACKEND", "direct")
    hl.env("LIBVA_DRIVER_NAME", "nvidia")
    hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
end
if gpus then gpus:close() end


