---------------------
---- KEYBINDINGS ----
---------------------

-- macOS layout (see keyd-default.conf): Left Alt is Cmd, Super is Option.
-- keyd turns the Cmd system shortcuts into Ctrl+Super combos, bound under "macOS" below.
-- Super itself is the window-management key; focus moves with Super+arrows or h/j/k/l.
local mainMod = "SUPER" -- Sets "Windows" key as main modifier

hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("pkill -x wofi || ~/.local/bin/jmpd-power-menu"))
hl.bind(mainMod .. " + SHIFT + Escape", hl.dsp.exec_cmd("uwsm stop"))  -- log out; uwsm stops the session's services first
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("uwsm-app -- brave"))
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + h/j/k/l or arrows
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- macOS: Cmd shortcuts, sent by keyd
local shots = "mkdir -p ~/Pictures/Screenshots && f=~/Pictures/Screenshots/$(date +%F_%H-%M-%S).png"
hl.bind("ALT + F4",              hl.dsp.window.close())                       -- Cmd+Q
hl.bind(mainMod .. " + Q",       hl.dsp.window.close())                       -- Super+Q
hl.bind("CTRL + SUPER + space",  hl.dsp.exec_cmd(menu))                       -- Cmd+Space
hl.bind(mainMod .. " + space",   hl.dsp.exec_cmd(menu))                       -- Super+Space, as in Omarchy
hl.bind(mainMod .. " + SHIFT + space",        hl.dsp.exec_cmd("~/.local/bin/jmpd-theme bg-next"))  -- next wallpaper
hl.bind(mainMod .. " + CTRL + V",             hl.dsp.exec_cmd("pkill -x wofi || ~/.local/bin/jmpd-clipboard"))  -- clipboard history
hl.bind(mainMod .. " + CTRL + SHIFT + space", hl.dsp.exec_cmd("pkill -x wofi || ~/.local/bin/jmpd-theme"))  -- theme menu
hl.bind("CTRL + SUPER + Tab",    hl.dsp.window.cycle_next())                  -- Cmd+Tab
hl.bind("CTRL + SUPER + M",      hl.dsp.window.move({ workspace = "special:magic", follow = false })) -- Cmd+M
hl.bind("CTRL + SUPER + H",      hl.dsp.window.move({ workspace = "special:magic", follow = false })) -- Cmd+H
hl.bind("CTRL + SUPER + Q",      hl.dsp.exec_cmd("hyprlock"))                 -- Ctrl+Cmd+Q
hl.bind("CTRL + SUPER + left",   hl.dsp.focus({ workspace = "e-1" }))         -- Ctrl+Left
hl.bind("CTRL + SUPER + right",  hl.dsp.focus({ workspace = "e+1" }))         -- Ctrl+Right
hl.bind("CTRL + SUPER + 3",      hl.dsp.exec_cmd(shots .. ' && grim "$f" && wl-copy < "$f"'))                  -- Cmd+Shift+3
hl.bind("CTRL + SUPER + 4",      hl.dsp.exec_cmd(shots .. ' && grim -g "$(slurp)" "$f" && wl-copy < "$f"'))    -- Cmd+Shift+4
-- Pick an area, then annotate in satty (like flameshot): Enter copies and closes, Ctrl+S saves
local annotate = shots .. ' && grim -g "$(slurp)" - | satty --filename - --output-filename "$f" --copy-command wl-copy'
    .. ' --actions-on-enter save-to-clipboard,exit --early-exit copy save'
hl.bind("CTRL + SUPER + 5",      hl.dsp.exec_cmd(annotate))                   -- Cmd+Shift+5
hl.bind("Print",                 hl.dsp.exec_cmd(annotate))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness, with swayosd's on-screen level
local osd = "swayosd-client --monitor \"$(hyprctl monitors -j | jq -r '.[] | select(.focused) | .name')\" "
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd(osd .. "--output-volume raise"),       { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd(osd .. "--output-volume lower"),       { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd(osd .. "--output-volume mute-toggle"), { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd(osd .. "--input-volume mute-toggle"),  { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd(osd .. "--brightness raise"),          { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd(osd .. "--brightness lower"),          { locked = true, repeating = true })

-- Lid closed: keep everything running, just turn the internal screen off
-- (logind ignores the lid, see system/logind-lid.conf)
hl.bind("switch:on:Lid Switch",  hl.dsp.dpms({ action = "disable", monitor = "eDP-1" }), { locked = true })
hl.bind("switch:off:Lid Switch", hl.dsp.dpms({ action = "enable",  monitor = "eDP-1" }), { locked = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Screensaver (bin/jmpd-screensaver) covers the whole screen
hl.window_rule({
    name  = "screensaver",
    match = { class = "jmpd.screensaver" },

    float      = true,
    fullscreen = true,
})

-- Steam and its games (class steam_app_<id>) hold off hypridle while fullscreen: no screensaver
-- or lock in the middle of a game played with a controller
hl.window_rule({
    name  = "steam-idle-inhibit",
    match = { class = "^(steam|steam_app_.*)$" },

    idle_inhibit = "fullscreen",
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
